package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter.getCounts(int index).
 */
public class MultidimensionalCounter_getCounts_TriageGen2Test {











    @Test
    public void testGetCounts_TwoDimensions() {
        // 3x4 counter
        MultidimensionalCounter counter = new MultidimensionalCounter(3, 4);

        // Index 0: [0, 0]
        assertArrayEquals(new int[]{0, 0}, counter.getCounts(0));

        // Index 4: 4 / 4 = 1, 4 % 4 = 0 -> [1, 0]
        assertArrayEquals(new int[]{1, 0}, counter.getCounts(4));

        // Index 5: [1, 1]
        assertArrayEquals(new int[]{1, 1}, counter.getCounts(5));

        // Index 11: [2, 3]
        assertArrayEquals(new int[]{2, 3}, counter.getCounts(11));
    }




}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter.getCounts(int index).
 */
public class MultidimensionalCounter_getCounts_TriageGen2Test {













    @Test
    public void testGetCounts_ThreeDimensions() {
        // 2x2x2 counter
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 2, 2);

        // index 0 -> [0,0,0]
        assertArrayEquals(new int[]{0, 0, 0}, counter.getCounts(0));

        // index 1 -> [0,0,1]
        assertArrayEquals(new int[]{0, 0, 1}, counter.getCounts(1));

        // index 2 -> [0,1,0]
        assertArrayEquals(new int[]{0, 1, 0}, counter.getCounts(2));

        // index 3 -> [0,1,1]
        assertArrayEquals(new int[]{0, 1, 1}, counter.getCounts(3));

        // index 4 -> [1,0,0]
        assertArrayEquals(new int[]{1, 0, 0}, counter.getCounts(4));

        // index 7 -> [1,1,1]
        assertArrayEquals(new int[]{1, 1, 1}, counter.getCounts(7));
    }


}

