/**
 * Unit tests for MultidimensionalCounter.getCounts(int index).
 */
public class MultidimensionalCounter_getCounts_TriageGen2Test {















    @Test
    public void testGetCounts_LargeDimensions() {
        // Testing the loop logic with more dimensions
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 2, 2, 2, 2);
        // index 31 is the last element (2^5 - 1)
        int[] expected = {1, 1, 1, 1, 1};
        assertArrayEquals(expected, counter.getCounts(31));

        // index 1
        int[] expected1 = {0, 0, 0, 0, 1};
        assertArrayEquals(expected1, counter.getCounts(1));
    }
}
